class Solution {
private:
    struct Cell {
        int r, c;
        bool operator==(const Cell& o) const { return r == o.r && c == o.c; }
    };
    struct CellHash {
        size_t operator()(const Cell& p) const { return hash<int>()(p.r) ^ (hash<int>()(p.c) << 16); }
    };
public:
    int findShortestPath(GridMaster &master) {
        unordered_map<Cell, int, CellHash> grid;
        Cell target = {100000, 100000};
        vector<tuple<char, char, int, int>> dirs = {
            {'U', 'D', -1, 0}, {'D', 'U', 1, 0}, {'L', 'R', 0, -1}, {'R', 'L', 0, 1}
        };

        function<void(int, int)> dfs = [&](int r, int c) {
            if (master.isTarget()) {
                target = {r, c};
            }
            for (auto& [fwd, bwd, dr, dc] : dirs) {
                int nr = r + dr, nc = c + dc;
                Cell nextCell = {nr, nc};
                if (grid.find(nextCell) == grid.end() && master.canMove(fwd)) {
                    int cost = master.move(fwd);
                    grid[nextCell] = cost;
                    dfs(nr, nc);
                    master.move(bwd);
                }
            }
        };

        grid[{0, 0}] = 0;
        dfs(0, 0);
        if (target.r == 100000) return -1;

        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> pq;
        unordered_map<Cell, int, CellHash> dist;
        pq.push({0, 0, 0});
        dist[{0, 0}] = 0;

        while (!pq.empty()) {
            auto [d, r, c] = pq.top();
            pq.pop();
            if (r == target.r && c == target.c) return d;
            if (d > dist[{r, c}]) continue;
            for (auto& [fwd, bwd, dr, dc] : dirs) {
                int nr = r + dr, nc = c + dc;
                Cell nxt = {nr, nc};
                if (grid.find(nxt) != grid.end()) {
                    int w = grid[nxt];
                    if (dist.find(nxt) == dist.end() || d + w < dist[nxt]) {
                        dist[nxt] = d + w;
                        pq.push({d + w, nr, nc});
                    }
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int findShortestPath(GridMaster master) {
        Map<String, Integer> grid = new HashMap<>();
        int[] target = null;
        char[] fwd = {'U', 'D', 'L', 'R'};
        char[] bwd = {'D', 'U', 'R', 'L'};
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        grid.put("0,0", 0);
        dfs(master, 0, 0, grid, fwd, bwd, dr, dc);
        for (String k : grid.keySet()) {
            if (k.startsWith("T:")) {
                String[] parts = k.substring(2).split(",");
                target = new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
                break;
            }
        }
        if (target == null) return -1;

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        Map<String, Integer> dist = new HashMap<>();
        pq.offer(new int[]{0, 0, 0});
        dist.put("0,0", 0);

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], r = top[1], c = top[2];
            if (r == target[0] && c == target[1]) return d;
            String key = r + "," + c;
            if (d > dist.getOrDefault(key, Integer.MAX_VALUE)) continue;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                String nkey = nr + "," + nc;
                if (grid.containsKey(nkey)) {
                    int w = grid.get(nkey);
                    if (d + w < dist.getOrDefault(nkey, Integer.MAX_VALUE)) {
                        dist.put(nkey, d + w);
                        pq.offer(new int[]{d + w, nr, nc});
                    }
                }
            }
        }
        return -1;
    }

    private void dfs(GridMaster master, int r, int c, Map<String, Integer> grid, char[] fwd, char[] bwd, int[] dr, int[] dc) {
        if (master.isTarget()) {
            grid.put("T:" + r + "," + c, 0);
        }
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            String nkey = nr + "," + nc;
            if (!grid.containsKey(nkey) && master.canMove(fwd[i])) {
                int cost = master.move(fwd[i]);
                grid.put(nkey, cost);
                dfs(master, nr, nc, grid, fwd, bwd, dr, dc);
                master.move(bwd[i]);
            }
        }
    }
}

var findShortestPath = function(master) {
  const grid = new Map();
  let target = null;
  const dirs = [
    { fwd: 'U', bwd: 'D', dr: -1, dc: 0 },
    { fwd: 'D', bwd: 'U', dr: 1, dc: 0 },
    { fwd: 'L', bwd: 'R', dr: 0, dc: -1 },
    { fwd: 'R', bwd: 'L', dr: 0, dc: 1 }
  ];

  function dfs(r, c) {
    if (master.isTarget()) {
      target = [r, c];
    }
    for (const { fwd, bwd, dr, dc } of dirs) {
      const nr = r + dr, nc = c + dc;
      const key = `${nr},${nc}`;
      if (!grid.has(key) && master.canMove(fwd)) {
        const cost = master.move(fwd);
        grid.set(key, cost);
        dfs(nr, nc);
        master.move(bwd);
      }
    }
  }

  grid.set('0,0', 0);
  dfs(0, 0);
  if (!target) return -1;

  const pq = [[0, 0, 0]];
  const dist = new Map([['0,0', 0]]);

  while (pq.length > 0) {
    pq.sort((a, b) => a[0] - b[0]);
    const [d, r, c] = pq.shift();
    if (r === target[0] && c === target[1]) return d;
    const key = `${r},${c}`;
    if (d > (dist.get(key) ?? Infinity)) continue;

    for (const { dr, dc } of dirs) {
      const nr = r + dr, nc = c + dc;
      const nkey = `${nr},${nc}`;
      if (grid.has(nkey)) {
        const w = grid.get(nkey);
        if (d + w < (dist.get(nkey) ?? Infinity)) {
          dist.set(nkey, d + w);
          pq.push([d + w, nr, nc]);
        }
      }
    }
  }
  return -1;
};
